package com.bookstore.order.controller;
import com.bookstore.order.dto.OrderRequest; import org.springframework.security.core.Authentication; import com.bookstore.order.entity.Order; import com.bookstore.order.repository.OrderRepository; import com.bookstore.order.service.OrderService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderService service; private final OrderRepository repo; public OrderController(OrderService service,OrderRepository repo){this.service=service;this.repo=repo;} @GetMapping public List<Order> all(Authentication a){return repo.findByUserUsername(a.getName());} @PostMapping public Order create(Authentication a,@Valid @RequestBody OrderRequest r){return service.create(a.getName(),r);} }
